Pseudo-code:

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state : GateState := IDLE;
    lastOpenBtn : BOOL := FALSE;
    lastCloseBtn : BOOL := FALSE;
END_VAR

// Edge detection
bOpenRising := openBtn AND NOT lastOpenBtn;
bCloseRising := closeBtn AND NOT lastCloseBtn;

// Update last values
lastOpenBtn := openBtn;
lastCloseBtn := closeBtn;

// Main state machine
CASE state OF
    IDLE:
        motorUp := FALSE;
