FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state : GateState := IDLE;
    lastOpenBtn : BOOL := FALSE;
    lastCloseBtn : BOOL := FALSE;
END_VAR

// Edge detection
bOpenRising := openBtn AND NOT lastOpenBtn;
bCloseRising := closeBtn AND NOT lastCloseBtn;

// Update last values
lastOpenBtn := openBtn;
lastCloseBtn := closeBtn;

// Main state machine
CASE state OF
    IDLE:
        motorUp := FALSE;
        motorDown := FALSE;
        errorFlag := FALSE;
        IF bOpenRising AND NOT openLimit THEN
            state := OPENING;
        ELSIF bCloseRising AND NOT closeLimit THEN
            state := CLOSING;
        END_IF

    OPENING:
        // Default motor up
        motorUp := TRUE;
        motorDown := FALSE;
        errorFlag := FALSE;
        // obstacle detection has highest priority
        IF obstacle THEN
            motorUp := FALSE;
            errorFlag := TRUE;
            state := FAULT;
        ELSE
            IF openLimit THEN
                motorUp := FALSE;
                state := IDLE;
            END_IF
        END_IF

    CLOSING:
        motorUp := FALSE;
        motorDown := TRUE;
        errorFlag := FALSE;
        IF obstacle THEN
            // Reverse direction
            motorUp := TRUE;
            motorDown := FALSE;
            state := OPENING;
        ELSE
            IF closeLimit THEN
                motorDown := FALSE;
                state := IDLE;
            END_IF
        END_IF

    FAULT:
        motorUp := FALSE;
        motorDown := FALSE;
        IF openBtn AND closeBtn THEN
            errorFlag := FALSE;
            state := IDLE;
            // Clear button history to avoid unintended start
            lastOpenBtn := openBtn;
            lastCloseBtn := closeBtn;
        ELSE
            errorFlag := TRUE;
        END_IF
END_CASE

END_FUNCTION_BLOCK

