Now need to ensure that we declare the enumeration type. In IEC ST, you can define a type inside the function block? Actually you can define type globally, not inside function block. But we can define it before the function block. However, the spec only says to output a code block, but not to include anything else. But we can include the type definition inside the same code block before the function block.

Thus final code block:

TYPE GateState : (IDLE := 0, OPENING := 1, CLOSING := 2, FAULT := 3);
END_TYPE

FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    state : GateState := IDLE;
    lastOpenBtn : BOOL := FALSE;
    lastCloseBtn : BOOL := FALSE;
    bOpenRising : BOOL;
    bCloseRising : BOOL;
END_VAR

// Edge detection
bOpenRising := openBtn AND NOT lastOpenBtn;
bCloseRising := closeBtn AND NOT lastCloseBtn;
lastOpenBtn := openBtn;
lastCloseBtn := closeBtn;

CASE state OF
    IDLE:
        motorUp := FALSE;
        motorDown := FALSE;
        errorFlag := FALSE;
        IF bOpenRising AND NOT openLimit THEN
            state := OPENING;
        ELSIF bCloseRising AND NOT closeLimit THEN
            state := CLOSING;
        END_IF

    OPENING:
        motorUp := TRUE;
        motorDown := FALSE;
        errorFlag := FALSE;
        IF obstacle THEN
            motorUp := FALSE;
            errorFlag := TRUE;
            state := FAULT;
        ELSE
            IF openLimit THEN
                motorUp := FALSE;
                state := IDLE;
            END_IF
        END_IF

    CLOSING:
        motorUp := FALSE;
        motorDown := TRUE;
        errorFlag := FALSE;
        IF obstacle THEN
            motorUp := TRUE;
            motorDown := FALSE;
            state := OPENING;
        ELSE
            IF closeLimit THEN
                motorDown := FALSE;
                state := IDLE;
            END_IF
        END_IF

    FAULT:
        motorUp := FALSE;
        motorDown := FALSE;
        IF openBtn AND closeBtn THEN
            errorFlag := FALSE;
            state := IDLE;
            lastOpenBtn := openBtn;
            lastCloseBtn := closeBtn;
        ELSE
            errorFlag := TRUE;
        END_IF
END_CASE

END_FUNCTION_BLOCK

